// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/healthz", wrapper.GetHealth)
	router.GET(options.BaseURL+"/readyz", wrapper.GetReadiness)
	router.GET(options.BaseURL+"/v1/products/managed-ai", wrapper.GetManagedAIProduct)
	router.POST(options.BaseURL+"/v1/attest/challenges", wrapper.IssueAttestationChallenge)
	router.POST(options.BaseURL+"/v1/attest/keys", wrapper.RegisterAttestationKey)
	router.POST(options.BaseURL+"/v1/dev/entitlements/activate", wrapper.ActivateDevelopmentEntitlement)
	router.POST(options.BaseURL+"/v1/entitlements/transactions", wrapper.SynchronizeSubscriptionTransaction)
	router.POST(options.BaseURL+"/v1/app-store/notifications", wrapper.ProcessAppStoreNotification)
	router.POST(options.BaseURL+"/v1/privacy/consents", wrapper.RecordPrivacyConsents)
	router.DELETE(options.BaseURL+"/v1/privacy/data", wrapper.DeletePrivacyData)
	router.GET(options.BaseURL+"/v1/ai/quota", wrapper.GetAIQuota)
	router.POST(options.BaseURL+"/v1/ai/operations/journal.organize/responses", wrapper.OrganizeJournal)
}

